mapper.select:
SELECT 
  FROM media_assets
 WHERE 

   AND asset_type = #{type}


   AND status = #{status}


   AND (LOWER(original_filename) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(COALESCE(storage_key, '')) LIKE LOWER(CONCAT('%', #{search}, '%')))


   AND (created_at < #{cursorCreatedAt}
        OR (created_at = #{cursorCreatedAt} AND id < #{cursorId,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}))

 ORDER BY created_at DESC, id DESC
 LIMIT #{limit}

SELECT 
  FROM media_assets
 WHERE account_id = #{accountId}
   AND id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND status <> 'DELETED'
   AND deleted_at IS NULL

mapper.update:
UPDATE media_assets m
   SET status = 'DELETED',
       deleted_at = CURRENT_TIMESTAMP
 WHERE m.account_id = #{accountId}
   AND m.project_id = #{projectId,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND m.id = #{id,typeHandler=com.narrativex.backend.feature.assets.infrastructure.persistence.mybatis.MediaAssetUuidTypeHandler}
   AND m.status = 'READY'
   AND m.deleted_at IS NULL
   AND NOT EXISTS (
         SELECT 1
           FROM narration_parts p
          WHERE p.media_asset_id = m.id
   )
